We start by proving the following auxiliary statement:

\begin{restatable}[$AB$-Decomposition]{theorem}{thmtwopathdecomposition} \label{thm:2-path-decomposition}
Let $A \in \set{0, 1}^{X \times Y}, B \in \set{0, 1}^{Y \times Z}$, let $\epsilon \in (0, 1)$ and~\makebox{$d \geq 1$}. There is an algorithm $\ABDecomposition(X, Y, Z, A, B, \epsilon, d)$ that computes a collection of tuples $\set{(X_k, Y_k, Z_k, A_k, B_k)}_{k=1}^K$, where $X_k \subseteq X$, $Y_k \subseteq Y$, $Z_k \subseteq Z$, $A_k \in \set{0, 1}^{X_k \times Y_k}$, \smash{$B_k \in \set{0, 1}^{Y_k \times Z_k}$} such that
\begin{enumerate}
    \item $A B = \sum_{k=1}^K A_k B_k$.
    \item For all $k \in [K]$:
    \begin{enumerate}[label=(\roman*)]
        \item $\Ex[A_k] \leq 2^{-d}$ or $\Ex[B_k] \leq 2^{-d}$, or
        \item $A_k$ and $B_k^T$ are both $(\epsilon, 2, d)$-regular and $\epsilon$-min-degree. 
    \end{enumerate}
    \item $\sum_{k=1}^K |X_k| \, |Y_k| \, |Z_k| \leq 2(d + 2)^2 \cdot |X| \, |Y| \, |Z|$.
    \item $K \leq \exp(d^7 \poly(\epsilon^{-1}))$.
\end{enumerate}
The algorithm is deterministic and runs in time $n^2 \cdot \exp(d^7 \poly(\epsilon^{-1}))$ (where $n = |X| + |Y| + |Z|$).
\end{restatable}
\begin{proof}
We start with the description of the algorithm; see \cref{alg:2-path-decomposition} for the pseudocode. Throughout we assume an additional input parameter $0 \leq h \leq d$ which acts somewhat as the recursion depth of the algorithm. For the initial call, we set $h = 0$.

The algorithm has two bases cases. If $B$ is sufficiently sparse, $\Ex[B] \leq 2^{-d}$, then we return the trivial decomposition $\set{(X, Y, Z, A, B)}$ (\cref{alg:2-path-decomposition:line:sparse,alg:2-path-decomposition:line:sparse-return}). Moreover, if the algorithm has reached recursion depth $h = d$, then we return a trivial decomposition of size at most $2^d$. Specifically, we split $B$ into submatrices $B_1, \dots, B_{2^d} \in \set{0, 1}^{Y \times Z}$ each of density at most $2^{-d}$ and return the decomposition $\set{(X, Y, Z, A, B_i)}_{i=1}^{2^d}$ (\crefrange{alg:2-path-decomposition:line:depth}{alg:2-path-decomposition:line:depth-return}).

Otherwise, run \smash{$\RegCube(X, Y, Z, A, B, \epsilon, \gamma, d)$} (\cref{lem:good-cube}) with the parameter \smash{$\gamma = \frac{1}{2(d+2)^2}$}. This output consists of sets $Y^* \subseteq Y$, $Z^* \subseteq Z$ and a set $\set{(X_\ell, Y_\ell, Z_\ell, A_\ell)}_{\ell=1}^L$ (\cref{alg:2-path-decomposition:line:reg-cube}). For each~\makebox{$\ell \in [L]$} we write $B_\ell \gets B[Y_\ell, Z_\ell]$ and $B_\ell' \gets B[Y_\ell, Z^* \setminus Z_\ell]$. We then recursively compute, for each $\ell \in [L]$, the decomposition $\mathcal S_\ell$ of $(X_\ell, Y_\ell, Z^* \setminus Z_\ell, A_\ell, B_\ell')$ (\crefrange{alg:2-path-decomposition:line:loop}{alg:2-path-decomposition:line:loop-recur}). Moreover, we recursively compute the decomposition $\mathcal S^*$ of $(X, Y, Z, A, B - B[Y^*, Z^*])$ (\cref{alg:2-path-decomposition:line:recur}; here, we denote by $B - B[Y^*, Z^*]$ the matrix obtained from $B$ after zeroing out the entries in $B[Y^*, Z^*]$). Finally, we return $\bigcup_{\ell=1}^L \set{(X_\ell, Y_\ell, Z_\ell, A_\ell, B_\ell)} \cup \bigcup_{\ell=1}^L \mathcal S_\ell \cup \mathcal S^*$ (\cref{alg:2-path-decomposition:line:return}).

\begin{algorithm}[t]
\caption{Implements the algorithm from \cref{thm:2-path-decomposition}.} \label{alg:2-path-decomposition}
\begin{algorithmic}[1]
    \Procedure{\ABDecompositionp}{$X, Y, Z, A, B, \epsilon, d, h$}
        \If{$\Ex[B] \leq 2^{-d}$} \label{alg:2-path-decomposition:line:sparse}
            \State\Return $\set{(X, Y, Z, A, B)}$ \label{alg:2-path-decomposition:line:sparse-return}
        \EndIf
        \If{$h = d$} \label{alg:2-path-decomposition:line:depth}
            \State Arbitrarily partition $B$ into submatrices $B_1, \dots, B_{2^d} \in \set{0, 1}^{Y \times Z}$ of density at most $2^{-d}$\label{alg:2-path-decomposition:line:depth-trivial-decomp}
            \State\Return \smash{$\set{(X, Y, Z, A, B_i)}_{i=1}^{2^d}$}\label{alg:2-path-decomposition:line:depth-return}
        \EndIf
        \State Compute \smash{$Y^*, Z^*, \set{(X_\ell, Y_\ell, Z_\ell, A_\ell)}_{\ell=1}^L \gets \RegCube(X, Y, Z, A, B, \epsilon, \frac{1}{2(d+2)^2}, d)$} \label{alg:2-path-decomposition:line:reg-cube}
        \ForEach{$\ell \in [L]$} \label{alg:2-path-decomposition:line:loop}
            \State Let $B_\ell \gets B[Y_\ell, Z_\ell]$ and $B_\ell' \gets B[Y_\ell, Z^* \setminus Z_\ell]$ \label{alg:2-path-decomposition:line:loop-names}
            \State Compute $\mathcal S_\ell \gets \ABDecompositionp(X_\ell, Y_\ell, Z^* \setminus Z_\ell, A_\ell, B_\ell', \epsilon, d, h + 1)$ \label{alg:2-path-decomposition:line:loop-recur}
        \EndForEach
        \State Compute $\mathcal S^* \gets \ABDecompositionp(X, Y, Z, A, B - B[Y^*, Z^*], \epsilon, d, h)$ \label{alg:2-path-decomposition:line:recur}
        \State\Return $\bigcup_{\ell=1}^L \set{(X_\ell, Y_\ell, Z_\ell, A_\ell, B_\ell)} \cup \bigcup_{\ell=1}^L \mathcal S_\ell \cup \mathcal S^*$ \label{alg:2-path-decomposition:line:return}
    \EndProcedure

    \bigskip
    \Procedure{\ABDecomposition}{$X, Y, Z, A, B, \epsilon, d$}
        \State\Return $\ABDecompositionp(X, Y, Z, A, B, \epsilon, d, 0)$
    \EndProcedure
\end{algorithmic}
\end{algorithm}

\paragraph{Correctness of Property 1}
For a set $\mathcal S$ as returned by the algorithm, we write
\begin{equation*}
    \Sigma(\mathcal S) = \sum_{(X', Y', Z', A', B') \in \mathcal S} A' B',
\end{equation*}
where, as in the theorem statement, we interpret each term $A' B'$ in the sum as an $X \times Z$-matrix by extending with zeros. The goal is to prove that $\Sigma(\mathcal S) = A B$, where $\mathcal S$ is the set returned by the algorithm on input $(X, Y, Z, A, B)$. This is clear in both base cases. So assume that the algorithm recurses. Then by induction:
\begin{align*}
    \Sigma(\mathcal S) &= \sum_{\ell=1}^L A_\ell B_\ell + \sum_{\ell=1}^L \Sigma(\mathcal S_\ell) + \Sigma(\mathcal S^*) \\
    &= \sum_{\ell=1}^L A_\ell B_\ell + \sum_{\ell=1}^L A_\ell B_\ell' + A B - A[X, Y^*] B[Y^*, Z^*] \\
    &= \sum_{\ell=1}^L A_\ell B[Y_\ell, Z^*] + A B - A[X, Y^*] B[Y^*, Z^*] \\[1ex]
    &= A[X, Y^*] B[Y^*, Z^*] + A B - A[X, Y^*] B[Y^*, Z^*] \\[1ex]
    &= AB;
\end{align*}
here, in the second-to-last step we have applied Property~1 of \cref{lem:good-cube}.


\paragraph{Correctness of Property 2}
In both base cases we return partitions in which all parts $B_k$ are sparse, $\Ex[B_k] \leq 2^{-d}$. In the recursive case the output consists of the union of three different sets: For each $(X_\ell, Y_\ell, Z_\ell, A_\ell, B_\ell)$ the claim follows from Property~2 of \cref{lem:good-cube}, and for each element in $\mathcal S_\ell$ or $\mathcal S^*$ the claim holds by induction.

\paragraph{Correctness of Property 3}
For a collection $\mathcal S$ of tuples as returned by the algorithm, let us write
\begin{equation*}
    C(\mathcal S) = \sum_{(X', Y', Z', A', B') \in \mathcal S} |X'| \, |Y'| \, |Z'|.
\end{equation*}
Our goal is to prove that $C(\mathcal S) \leq 2^{h+1} \cdot (d + 2)^2 \cdot |X| \, |Y| \, |Z|$, where $\mathcal S$ is the output of our algorithm with inputs $(X, Y, Z, A, B, \epsilon, d, h)$. In the sparse case, if $\Ex[B] \leq 2^{-d}$, then we return the trivial decomposition with $C(\mathcal S) = |X| \, |Y| \, |Z|$. We prove by induction that otherwise the following bound applies:
\begin{equation*}
    C(\mathcal S) \leq 2^{h+1} \cdot (d + 2) (d + 1 - \log(\Ex[B]^{-1})) \cdot |X| \, |Y| \, |Z|
\end{equation*}
Clearly, this upper bound is true if $h = d$, so suppose that $h < d$. Then the algorithm recurses and we report $\mathcal S$ with $C(\mathcal S) = \sum_{\ell=1}^L |X_\ell| \, |Y_\ell| \, |Z_\ell| + \sum_{\ell=1}^L C(\mathcal S_\ell) + C(\mathcal S^*)$. In the following we bound these three contributions individually.

For the first contribution we readily exploit Property~4 of \cref{lem:good-cube}:
\begin{equation} \label{thm:2-path-decomposition:eq:1}
    \sum_{\ell=1}^L |X_\ell| \, |Y_\ell| \, |Z_\ell| \leq (d + 2) \cdot |X| \, |Y^*| \, |Z^*| \leq 2^h \cdot (d + 2) \cdot |X| \, |Y^*| \, |Z^*|.
\end{equation}
For the second contribution we exploit Property~5 of \cref{lem:good-cube}:
\begin{align}
    \sum_{\ell=1}^L C(\mathcal S_\ell)
    &\leq \sum_{\ell=1}^L 2^{h+1} \cdot (d + 2)^2 \cdot |X_\ell| \, |Y_\ell| \, |Z^* \setminus Z_\ell| \nonumber \\[.5ex]
    &\leq 2^{h+1} \cdot \gamma \cdot (d + 2)^3 \cdot |X| \, |Y^*| \, |Z^*| \nonumber \\[.5ex]
    &\leq 2^h \cdot (d + 2) \cdot |X| \, |Y^*| \, |Z^*|. \label{thm:2-path-decomposition:eq:2}
\end{align}
Here, in the last step, we have used our choice of \smash{$\gamma = \frac{1}{2(d + 2)^2}$}. For the third contribution, we distinguish two cases. If the density $\delta^*$ of the subgraph $B - B[Y^*, Z^*]$ is smaller than $2^{-d}$, then $C(\mathcal S^*) \leq |X| \, |Y| \, |Z|$. Otherwise, we have \smash{$\delta^* \leq \Ex[B] \cdot (1 - \frac{|Y^*| \, |Z^*|}{|Y| \, |Z|})$} (since $\Ex[B[Y^*, Z^*]] \geq \Ex[B]$ by Property~3 of \cref{lem:good-cube}) and therefore:
\begin{align}
    C(\mathcal S^*)
    &\leq 2^{h+1} \cdot (d + 2)(d + 1 - \log(\Ex[B]^{-1} \cdot (1 - \tfrac{|Y^*| \, |Z^*|}{|Y| \, |Z|})^{-1})) \cdot |X| \, |Y| \, |Z| \nonumber \\
    &\leq 2^{h+1} \cdot (d + 2)(d + 1 - \log(\Ex[B]^{-1}) + \log(1 - \tfrac{|Y^*| \, |Z^*|}{|Y| \, |Z|})) \cdot |X| \, |Y| \, |Z| \nonumber \\
    &\leq 2^{h+1} \cdot (d + 2)(d + 1 - \log(\Ex[B]^{-1}) - \tfrac{|Y^*| \, |Z^*|}{|Y| \, |Z|}) \cdot |X| \, |Y| \, |Z| \nonumber \\
    &\leq 2^{h+1} \cdot (d + 2)(d + 1 - \log(\Ex[B]^{-1})) \cdot |X| \, |Y| \, |Z| - 2^{h+1} \cdot (d + 2) \cdot |X| \, |Y^*| \, |Z^*|. \label{thm:2-path-decomposition:eq:3}
\end{align}
Summing over all three contributions~\eqref{thm:2-path-decomposition:eq:1},~\eqref{thm:2-path-decomposition:eq:2} and~\eqref{thm:2-path-decomposition:eq:3} yields the claimed bound on $C(\mathcal S)$.

\paragraph{Correctness of Property 4}
Let $M = \exp(d^4 \gamma^{-1} \poly(\epsilon^{-1}))$ be such that $|Y^*| \, |Z^*| \geq |Y| \, |Z| \,/\, M$ for the sets $Y^*, Z^*$ returned by \cref{lem:good-cube}. Moreover, let $L = \exp(d^3 \poly(\epsilon^{-1}))$ be as in \cref{lem:good-cube}. We prove by induction that
\begin{equation*}
    K = |\mathcal S| \leq 2^d M \cdot (2^d M L + L)^{d+1-h} \cdot \Ex[B],
\end{equation*}
where $\mathcal S$ is the set returned by the algorithm. This bound is easily verified in the two base cases. If the algorithm recurses instead then $|\mathcal S| \leq L + \sum_{\ell=1}^L |\mathcal S_\ell| + |\mathcal S^*|$. By induction we can bound
\begin{equation*}
    |\mathcal S_\ell| \leq 2^d M \cdot (2^d M L + L)^{d-h},
\end{equation*}
and
\begin{align*}
    |\mathcal S^*| &\leq 2^d M \cdot (2^d M L + L)^{d+1-h} \cdot \parens{\Ex[B] - \Ex[B[Y^*, Z^*]] \cdot \tfrac{|Y^*| \, |Z^*|}{|Y| \, |Z|}} \\
    &\leq 2^d M \cdot (2^d M L + L)^{d+1-h} \cdot \parens*{\Ex[B] - \Ex[B[Y^*, Z^*]] \cdot \tfrac{1}{M}} \\
    &\leq 2^d M \cdot (2^d M L + L)^{d+1-h} \cdot \parens*{\Ex[B] - \tfrac{1}{2^d M}},
\end{align*}
using in the last step that $\Ex[B[Y^*, Z^*]] \geq \Ex[B]$ by Property~3 of \cref{lem:good-cube}. Combining these bounds, it follows that
\begin{align*}
    |\mathcal S|
    &\leq L + L \cdot 2^d M \cdot (2^d M L + L)^{d-h} + 2^d M \cdot (2^d M L + L)^{d+1-h} \cdot (\Ex[B] - \tfrac{1}{2^d M}) \\
    &\leq (2^d M L + L)^{d+1-h} - (2^d M L + L)^{d+1-h} + 2^d M \cdot (2^d M L + L)^{d+1-h} \cdot \Ex[B] \\
    &= 2^d M \cdot (2^d M L + L)^{d+1-h} \cdot \Ex[B].
\end{align*}
In the end we plug in values for $L$ and $M$ to obtain $|S| \leq \exp(d^5 \gamma^{-1} \poly(\epsilon^{-1})) = \exp(d^7 \poly(\epsilon^{-1}))$, as stated.

\paragraph{Running Time}
From the previous consideration we also learn that the number of recursive calls is bounded by $\exp(d^7 \poly(\epsilon^{-1}))$. In each recursive call, the dominant step is to call $\RegCube$ in time $n^2 \cdot \exp(d^3 \poly(\epsilon^{-1}))$. Hence, the total time is $n^2 \cdot \exp(d^7 \poly(\epsilon^{-1}))$.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
Let $G = (X, Y, Z, A, B, C)$ be a given tripartite graph. We design a recursive algorithm that lists all triangles in $G$. To this end, we maintain one (global) list of triangles and each recursive call of the algorithm appends triangles to this list. Let $n$ denote the total number of nodes in the original graph $G$ (at the top level of the recursion), and let $\gamma, \delta, \epsilon \in (0, 1)$ and $d \geq 4 / \epsilon$ be parameters to be determined later.

The first step is to call \cref{thm:2-path-decomposition} on input $(X, Y, Z, A, B, \epsilon, d)$ to compute a decomposition~$\set{(X_k, Y_k, Z_k, A_k, B_k)}_{k=1}^K$. For each $k \in [K]$, we write for convenience~\makebox{$C_k = C[X_k, Z_k]$} and~\makebox{$G_k = (X_k, Y_k, Z_k, A_k, B_k, C_k)$}. By the guarantee of \cref{thm:2-path-decomposition} this decomposition partitions the set of triangles in $G$, and thus the remaining goal is to separately list all triangles in the graphs~$G_k$. To this end, for each $k \in [K]$, we distinguish the following cases:
\begin{enumerate}
    \item\emph{If $\Ex[A_k] \leq 2^{-\epsilon d / 4}$ or $\Ex[B_k] \leq 2^{-\epsilon d / 4}$:} List all triangles in $G_k$ in time $\Order(|X_k| \, |Y_k| \, |Z_k| \,/\, 2^{\epsilon d / 4})$.
    \item\emph{If $\Ex[A_k] \leq \delta$ and $\Ex[B_k] \leq \delta$:} List all triangles in $G_k$ by \cref{lem:four-russians}.
    \item\emph{If $\Ex[B_k] \geq \delta$:} We further subdivide the graph $G_k$ based on the approximate degrees in $X_k$ with respect to $Z_k$. Specifically, let $L = \ceil{\epsilon d / 2}$ and split~$X_k$ into buckets $X_{k, 1}, \dots, X_{k, L}$ defined by
    \begin{align*}
        X_{k, \ell} &= \set{x \in X_k : 2^{-\ell} < \deg_{C_k}(x) \leq 2^{-\ell+1}} \quad\text{(for $1 \leq \ell < L$)}, \\
        X_{k, L} &= \set{x \in X_k : \deg_{C_k}(x) \leq 2^{-L+1}}.
    \end{align*}
    For each $\ell \in [L]$, we define the matrix $C_{k, i} \in \set{0, 1}^{X_k \times Z_k}$ as the submatrix of $C_k$ obtained by zeroing out all rows not in $X_i$. (That is, $C_{k, i}[x, z] = C_k[x, z]$ if $x \in X_i$ and $C_k[x, z] = 0$ otherwise.) Writing $G_{k, \ell} = (X_k, Y_k, Z_k, A_k, B_k, C_{k, \ell})$, our remaining goal is to list the disjoint union of triangles in the graphs $G_{k, \ell}$. For each~\makebox{$\ell \in [L]$}, we instead distinguish the following three subcases:
    \begin{enumerate}
        \item[3.1]\emph{If $\Ex[C_{k, \ell}] \leq 2^{-L+1}$:} List all triangles in $G_{k, \ell}$ in time $\Order(|X_k| \, |Y_k| \, |Z_k| \,/\, 2^L)$.
        \item[3.2]\emph{If $|X_{k, \ell}| < \gamma |X_k|$:} Recurse on $(X_{k, \ell}, Y_k, Z_k, A_k[X_{k, \ell}, Y_k], B_k, C_k[X_{k, \ell}, Z_k])$. (It is easy to check that the triangles in this graph are exactly the triangles in $G_{k, \ell}$.)
        \item[3.3]\emph{If $\Ex[C_{k, \ell}] > 2^{-L+1}$ and $|X_{k, \ell}| \geq \gamma |X_k|$:} List all triangles in $(Y_k, X_k, Z_k, A_k^T, C_{k, \ell}, B_k)$ by \cref{lem:four-russians}. (It is easy to check that the triangles in this graph are in one-to-one correspondence to the triangles in $G_{k, \ell}$.) Note that we have exchanged the node and edge sets such that \cref{lem:four-russians} benefits from minimizing $\Ex[A_k^T \circ C_{k, \ell}]$.  \end{enumerate}
    \item If $\Ex[A_k] \geq \delta$: This case is symmetric to the previous case. More precisely, we can reduce to the previous case by considering instead the graph $(Z_k, Y_k, X_k, B_k^T, A_k^T, C_k^T)$ whose triangles are clearly in one-to-one correspondence with those in $G_k$.
\end{enumerate}
Finally, we add one more rule to the algorithm: As soon as we reach recursion depth $H$ (for some parameter $H$ to be determined), we simply solve the instance by brute-force in time $\Order(|X| \, |Y| \, |Z|)$. This completes the description of the algorithm. The correctness should be clear from the in-text explanations.

\paragraph{Running Time}
It remains to bound the running time. For simplicity, we already fix all the parameters here, and then analyze the cases individually:
\begin{align*}
    \epsilon &= \frac{1}{160}, \\
    d &= \ceil{64000 \log\log n}\vphantom{\frac11}, \\
    \gamma &= \frac{1}{8L(d + 2)^2} = \Theta\parens*{\frac{1}{(\log\log n)^3}}, \\
    \delta &= \frac{(\log\log n)^2}{\gamma (\log n)^2} = \Theta\parens*{\frac{(\log\log n)^5}{(\log n)^2}}, \\
    H &= \ceil*{\log \frac{(\log n)^6}{(\log\log n)^{14}}} = \Theta(\log\log n).
\end{align*}

\begin{claim}[Cases 1 and 3.1] \label{thm:triangle-listing:clm:case-1}
The total running time of Cases~1 and~3.1 is $\Order(|X| \, |Y| \, |Z| / (\log n)^{99})$.
\end{claim}
\begin{proof}
The algorithm deals with Cases 1 and 3.1 in time $\Order(|X_k| \, |Y_k| \, |Z_k| / 2^{\epsilon d / 4})$, which, by our choice of the parameters $\epsilon, d$, is $\Order(|X_k| \, |Y_k| \, |Z_k| / (\log n)^{100})$. In total, taking into account all~$k \in [K]$, and possibly the at most $L$ repetitions of Case 3.1, by \cref{thm:2-path-decomposition} this becomes
\begin{equation*}
    \sum_{k=1}^K \Order\parens*{\frac{L \cdot |X_k| \, |Y_k| \, |Z_k|}{(\log n)^{100}}} = \Order\parens*{\frac{d^2 L \cdot |X| \, |Y| \, |Z|}{(\log n)^{100}}} = \Order\parens*{\frac{|X| \, |Y| \, |Z|}{(\log n)^{99}}}. \qedhere
\end{equation*}
\end{proof}

\begin{claim}[Case 2] \label{thm:triangle-listing:clm:case-2}
The total running time of Case~2 is
\begin{equation*}
    \Order\parens*{K n^{2.3} + |X| \, |Y| \, |Z| \cdot \frac{(\log \log n)^{14}}{(\log n)^6} + t_{\text{\normalfont 2}}},
\end{equation*}
where $t_{\text{\normalfont 2}}$ is the number of triangles listed in Case 2.
\end{claim}
\begin{proof}
We can assume that $\Ex[A_k], \Ex[B_k] > 2^{-d}$ whenever we enter Case 2 (since Case 1 did not apply). Thus, the regularity decomposition (\cref{thm:2-path-decomposition}) guarantees that~$A_k$ and~$B_k^T$ are both $(\epsilon, 2, d)$-regular and $\epsilon$-min-degree. As a corollary of \cref{thm:regular-product} we obtain that
\begin{equation*}
    \Ex[A_k \circ B_k] \leq (1 + 80 \epsilon) \Ex[A] \Ex[B] + 2^{-\epsilon d / 2} \leq \tfrac{3}{2} \Ex[A] \Ex[B] + \Ex[A] \Ex[B] \leq \tfrac{5}{2} \delta^2.
\end{equation*}
Write $t_{G_k}$ to denote the number of triangles in $G_k$. By \cref{lem:four-russians} and \cref{thm:2-path-decomposition}, it follows that Case~2 indeed takes total time
\begin{align*}
    &\sum_{\substack{k \in [K]\\\text{case 2}}} \Order\parens*{n^{2.3} + |X_k| \, |Y_k| \, |Z_k| \cdot \parens*{\frac{1}{(\log n)^{100}} + \frac{\delta^2 (\log \log n)^2}{(\log n)^2}} + t_{G_k}} \\
    &\qquad= \sum_{\substack{k \in [K]\\\text{case 2}}} \Order\parens*{n^{2.3} + |X_k| \, |Y_k| \, |Z_k| \cdot \frac{(\log \log n)^{12}}{(\log n)^6} + t_{G_k}} \\
    &\qquad= \Order\parens*{K n^{2.3} + |X| \, |Y| \, |Z| \cdot \frac{d^2 (\log \log n)^{12}}{(\log n)^6} + t_{\text{2}}} \\
    &\qquad= \Order\parens*{K n^{2.3} + |X| \, |Y| \, |Z| \cdot \frac{(\log \log n)^{14}}{(\log n)^6} + t_{\text{2}}}. \qedhere
\end{align*}
\end{proof}

\begin{claim}[Case 3.3] \label{thm:triangle-listing:clm:case-3.3}
The total running time of Case 3.3 is
\begin{equation*}
    \Order\parens*{K L n^{2.3} + \frac{|X| \, |Y| \, |Z|}{(\log n)^{99}} + t_{\text{\normalfont 3.3}}},
\end{equation*}
where $t_{\text{\normalfont 3.3}}$ is the number of triangles listed in Case~3.3.
\end{claim}
\begin{proof}
Focus on some pair $(k, \ell)$ that falls into Case 3.3, i.e., where $\Ex[B_k] \geq \delta$,~$\Ex[C_{k, \ell}] > 2^{-L+1}$ and $|X_{k, \ell}| \geq \gamma |X_k|$. We must have $\ell < L$ (as otherwise $\Ex[C_{k, \ell}] \leq 2^{-L+1}$). The analysis of this case is inspired by the previous algorithm for purely random graphs. Our goal is to prove that both (i) the number of 2-paths in $G_{k, \ell}$ (via the edge parts $A_k$ and $C_{k, \ell}$) and (ii) the number of triangles in~$G_{k, \ell}$ behave as if~$G_{k, \ell}$ was purely random.

We start with (i). By the construction of $C_{k, \ell}$, it is immediate that the density of~$C_{k, \ell}$ is at least
\begin{equation*}
    \Ex[C_{k, \ell}] \geq \frac{|X_{k, \ell}|}{|X_k|} \cdot 2^{-\ell} \geq \gamma \cdot 2^{-\ell}.
\end{equation*}
Therefore, we can bound
\begin{align*}
    \Ex[A_k^T \circ C_{k, \ell}] &= \Ex_{x \in X_k} \deg_{A_k}(x) \cdot \deg_{C_{k, \ell}}(x) \\
    &\leq \Ex_{x \in X_k} \deg_{A_k}(x) \cdot 2^{-\ell+1} \\
    &\leq 2\gamma^{-1} \cdot \Ex[A_k] \cdot \Ex[C_{k, \ell}].
\end{align*}

Next, we turn to (ii) and bound the number of triangles in $G_{k, \ell}$ from below. Using \cref{thm:regular-product} we infer that at most a $2^{-\epsilon d/2} \leq 2^{-L}$-fraction of the entries in $\Ex[A_k \circ B_k]$ does not fall into the range $[(1 - 80\epsilon) \Ex[A_k] \Ex[B_k], (1 + 80\epsilon) \Ex[A_k] \Ex[B_k]] = [\frac12 \Ex[A_k] \Ex[B_k], \frac32 \Ex[A_k] \Ex[B_k]]$. Therefore, the number of triangles in $G_{k, \ell}$ is at least
\begin{align*}
    t_{G_{k, \ell}}
    &\geq |X_k| \, |Y_k| \, |Z_k| \cdot \tfrac{1}{2} \Ex[A_k] \cdot \Ex[B_k] \cdot (\Ex[C_{k, \ell}] - 2^{-L}) \\
    &\geq |X_k| \, |Y_k| \, |Z_k| \cdot \tfrac{1}{4} \cdot \Ex[A_k] \cdot \Ex[B_k] \cdot \Ex[C_{k, \ell}] \\
    &\geq |X_k| \, |Y_k| \, |Z_k| \cdot \tfrac{\gamma}{8} \cdot \Ex[B_k] \cdot \Ex[A_k^T \circ C_{k, \ell}] \\
    &\geq |X_k| \, |Y_k| \, |Z_k| \cdot \tfrac{\gamma \delta}{8} \cdot \Ex[A_k^T \circ C_{k, \ell}].
\end{align*}

By combining both statements, we can bound the running time of \cref{lem:four-russians} as follows:
\begin{align*}
    &\sum_{\substack{k \in [K], \ell \in [L]\\\text{case 3.3}}} \Order\parens*{n^{2.3} + |X_k| \, |Y_k| \, |Z_k| \cdot \parens*{\frac{1}{(\log n)^{100}} + \frac{\Ex[A_k^T \circ C_{k, \ell}] \cdot (\log \log n)^2}{(\log n)^2}} + t_{G_{k, \ell}}} \\
    &\qquad\leq \sum_{\substack{k \in [K], \ell \in [L]\\\text{case 3.3}}} \Order\parens*{n^{2.3} + \frac{|X_k| \, |Y_k| \, |Z_k|}{(\log n)^{100}} + t_{G_{k, \ell}} \cdot \parens*{\frac{(\log\log n)^2}{(\gamma \delta/8) (\log n)^2} + 1}} \\
    &\qquad\leq \sum_{\substack{k \in [K], \ell \in [L]\\\text{case 3.3}}} \Order\parens*{n^{2.3} + \frac{|X_k| \, |Y_k| \, |Z_k|}{(\log n)^{100}} + t_{G_{k, \ell}}} \\
    &\qquad= \Order\parens*{K L n^{2.3} + \frac{d^2 L \cdot |X| \, |Y| \, |Z|}{(\log n)^{100}} + t_{\text{3.3}}} \\
    &\qquad= \Order\parens*{K L n^{2.3} + \frac{|X| \, |Y| \, |Z|}{(\log n)^{99}} + t_{\text{3.3}}}. \qedhere
\end{align*}
\end{proof}

It only remains to analyze Case~3.2, which involves recursive calls to our algorithm. Let us write $T(|X|, |Y|, |Z|, t, h)$ to express the total running time of our algorithm, given an input graph with vertex parts $X, Y, Z$ and with at most $t$ triangles, at recursion depth $0 \leq h \leq H$. Then finally:

\begin{claim}[Total Running Time] \label{thm:triangle-listing:clm:total}
The total running time is bounded by
\begin{equation*}
    T(|X|, |Y|, |Z|, t, h) \leq c \cdot \parens*{(2 K L)^{H-h} \cdot n^{2.3} + |X| \, |Y| \, |Z| \cdot \frac{(\log\log n)^{14} \cdot 2^{h+1}}{(\log n)^6} + t},
\end{equation*}
for some sufficiently large constant $c$.
\end{claim}
\begin{proof}
In the base case we have $T(|X|, |Y|, |Z|, t, H) = \Order(|X| \, |Y| \, |Z|)$ which indeed satisfied the claim (as $2^H \geq (\log n)^6 / (\log\log n)^{14}$). So focus on the case that $h < H$. Then, given the previous \cref{thm:triangle-listing:clm:case-1,thm:triangle-listing:clm:case-2,thm:triangle-listing:clm:case-3.3}, the running time of the Cases~1, 2,~3.1 and~3.3 is bounded by
\begin{equation} \label{thm:triangle-listing:clm:total:eq:others}
    c \cdot \parens*{K L n^{2.3} + |X| \, |Y| \, |Z| \cdot \frac{(\log \log n)^{14}}{(\log n)^6} + (t - t_{\text{3.2}})},
\end{equation}
where $c$ is some sufficiently large constant, and where $t_{\text{3.2}}$ is the number of triangles listed in Case~3.2 (such that $t - t_{\text{3.2}}$ is the number of triangles listed in all other cases). By induction we can bound the contribution of Case~3.2 as follows; recall that $|X_{k, \ell}| < \gamma |X_k|$ for any pair $(k, \ell)$ falling into Case~3.2:
\begin{align}
    &\sum_{\substack{k \in [K], \ell \in [L]\\\text{case 3.2}}} T(|X_{k, \ell}|, |Y_k|, |Z_k|, t_{G_{k, \ell}}, h + 1) \nonumber\\
    &\qquad\leq \sum_{\substack{k \in [K], \ell \in [L]\\\text{case 3.2}}} c \cdot \parens*{(2 K L)^{H-h-1} \cdot n^{2.3} + |X_{k, \ell}| \, |Y_k| \, |Z_k| \cdot \frac{(\log\log n)^{14} \cdot 2^{h+2}}{(\log n)^6} + t_{G_{k, \ell}}} \nonumber\\
    &\qquad\leq \sum_{\substack{k \in [K], \ell \in [L]\\\text{case 3.2}}} c \cdot \parens*{(2 K L)^{H-h-1} \cdot n^{2.3} + \gamma \cdot |X_k| \, |Y_k| \, |Z_k| \cdot \frac{(\log\log n)^{14} \cdot 2^{h+2}}{(\log n)^6} + t_{G_{k, \ell}}} \nonumber\\
    &\qquad c \cdot \parens*{K L (2 K L)^{H - h - 1} \cdot n^{2.3} + 2\gamma L (d + 2)^2 \cdot |X| \, |Y| \, |Z| \cdot \frac{(\log\log n)^{14} \cdot 2^{h+2}}{(\log n)^6} + t_{\text{3.2}}}. \label{thm:triangle-listing:clm:total:eq:recursive}
\end{align}
By our choice of parameters, $2 \gamma L (d + 2)^2 = \frac14$. Therefore, the total running time (which is obtained as the sum of \cref{thm:triangle-listing:clm:total:eq:others,thm:triangle-listing:clm:total:eq:recursive}) is at most
\begin{align*}
    &T(|X|, |Y|, |Z|, t, h) \\
    &\qquad\leq c \cdot \parens*{2 K L (2 K L)^{H - h - 1} \cdot n^{2.3} + |X| \, |Y| \, |Z| \cdot \frac{(\log \log n)^{14} \cdot 2^{h+1}}{(\log n)^6} + (t - t_{\text{3.2}} + t_{\text{3.2}})} \\
    &\qquad= c \cdot \parens*{(2 K L)^{H - h} \cdot n^{2.3} + |X| \, |Y| \, |Z| \cdot \frac{(\log \log n)^{14} \cdot 2^{h+1}}{(\log n)^6} + t},
\end{align*}
as stated.
\end{proof}

To obtain the time bound claimed in the theorem statement, recall that we initially call the algorithm at recursion depth $h = 0$, that $K \leq \exp(\poly(d, \epsilon^{-1})) = \exp(\poly(\log\log n))$, and that~\makebox{$H = \Order(\log\log n)$}. Hence, the term $(2 K L)^H \cdot n^{2.3} \leq n^{2.3+\order(1)}$ is negligible in the total running time.
\end{proof}
